<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;
class StudentDigitalCardController extends Controller{
private function access(Request $r,$id){$u=$r->user();$self=(int)$u->student_id===(int)$id;$staff=$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('director')||$u->hasRole('deputy_director')||$u->hasRole('academic_head')||$u->hasRole('curator')||$u->canDo('student_card.view')||$u->canDo('students.manage');abort_unless($self||$staff,403);return ['self'=>$self,'full'=>!$self&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('director')||$u->hasRole('deputy_director')||$u->hasRole('academic_head')||$u->canDo('student_card.full'))];}
private function has($t){return Schema::hasTable($t);}
public function show(Request $r,$student){$access=$this->access($r,$student);$p=$r->attributes->get('academic_period');$s=DB::table('students')->find($student);abort_if(!$s,404);
$membership=DB::table('student_group_memberships as m')->join('study_groups as g','g.id','=','m.study_group_id')->where(['m.student_id'=>$student,'m.academic_period_id'=>$p->id])->select('m.*','g.name as group_name')->first();
$history=DB::table('student_group_memberships as m')->join('study_groups as g','g.id','=','m.study_group_id')->leftJoin('academic_periods as ap','ap.id','=','m.academic_period_id')->where('m.student_id',$student)->select('m.*','g.name as group_name','ap.name as period_name')->orderByDesc('m.id')->get();
$grades=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where(['gr.student_id'=>$student,'l.academic_period_id'=>$p->id])->whereIn('gr.value',['2','3','4','5']);$avg=round((float)$grades->avg(DB::raw('CAST(gr.value AS REAL)')),2);
$att=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where(['a.student_id'=>$student,'l.academic_period_id'=>$p->id]);$an=(clone $att)->count();$attendance=$an?round((clone $att)->whereIn('a.status',['present','late'])->count()*100/$an,1):null;$absences=(clone $att)->whereNotIn('a.status',['present','late'])->count();
$results=DB::table('semester_results as sr')->leftJoin('subjects as sub','sub.id','=','sr.subject_id')->where(['sr.student_id'=>$student,'sr.academic_period_id'=>$p->id])->select('sr.*','sub.name as subject_name')->orderBy('sub.name')->get();$debts=$results->filter(fn($x)=>in_array(mb_strtolower((string)$x->value),['2','незачет','незачёт','не зачтено']))->count();
$practice=$this->has('practice_placements')?DB::table('practice_placements')->where(['student_id'=>$student,'academic_period_id'=>$p->id])->orderByDesc('id')->get():collect();
$dormitory=$this->has('dormitory_residents')?DB::table('dormitory_residents')->where('student_id',$student)->orderByDesc('id')->first():null;
$meals=$this->has('student_meal_assignments')?DB::table('student_meal_assignments as a')->leftJoin('meal_categories as c','c.id','=','a.meal_category_id')->where('a.student_id',$student)->select('a.*','c.name as category_name')->orderByDesc('a.id')->get():collect();
$loans=$this->has('library_loans')?DB::table('library_loans')->where('student_id',$student)->orderByDesc('id')->limit(20)->get():collect();
$requests=$this->has('service_requests')?DB::table('service_requests')->where('student_id',$student)->orderByDesc('id')->limit(20)->get():collect();
$achievements=$this->has('student_achievements')?DB::table('student_achievements')->where('student_id',$student)->orderByDesc('achievement_date')->get():collect();
$movements=$this->has('student_movements')?DB::table('student_movements')->where('student_id',$student)->orderByDesc('id')->get():collect();
$docs=DB::table('official_documents')->where('student_id',$student)->orderByDesc('id')->limit(30)->get();
$notes=$access['full']&&$this->has('student_card_notes')?DB::table('student_card_notes as n')->join('users as u','u.id','=','n.created_by')->where('n.student_id',$student)->select('n.*','u.name as author_name')->orderByDesc('n.id')->get():collect();
$private=$access['full']&&$this->has('student_private_profiles')?DB::table('student_private_profiles')->where('student_id',$student)->first():null;
$timeline=collect();foreach($movements as $x)$timeline->push(['date'=>$x->effective_date??$x->created_at,'icon'=>'↔','title'=>'Движение студента','text'=>$x->type??'']);foreach($achievements as $x)$timeline->push(['date'=>$x->achievement_date??$x->created_at,'icon'=>'🏆','title'=>$x->title,'text'=>$x->type]);foreach($practice as $x)$timeline->push(['date'=>$x->starts_on??$x->created_at,'icon'=>'🧰','title'=>'Практика','text'=>$x->status]);foreach($requests as $x)$timeline->push(['date'=>$x->created_at,'icon'=>'🎫','title'=>$x->number.' '.$x->title,'text'=>$x->status]);$timeline=$timeline->sortByDesc('date')->take(30);
return view('student-card.show',compact('s','p','access','membership','history','avg','attendance','absences','results','debts','practice','dormitory','meals','loans','requests','achievements','movements','docs','notes','private','timeline'));}
public function note(Request $r,$student){$a=$this->access($r,$student);abort_unless($a['full']||$r->user()->canDo('student_card.notes'),403);$d=$r->validate(['section'=>'required|in:general,academic,social,practice,administration','visibility'=>'required|in:administration,curator','title'=>'required|string|max:500','note'=>'required|string|max:10000']);DB::table('student_card_notes')->insert($d+['student_id'=>$student,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}